package in.ac.rtu.medicare.dao;
import in.ac.rtu.medicare.config.Database; import java.math.BigDecimal; import java.sql.*;
public class BillingDao {
 public long createInvoice(long appointmentId,BigDecimal amount)throws SQLException {if(amount.signum()<0)throw new IllegalArgumentException("Amount cannot be negative");try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement("INSERT INTO invoices(appointment_id,amount) SELECT id,? FROM appointments WHERE id=? AND status='COMPLETED'",Statement.RETURN_GENERATED_KEYS)){s.setBigDecimal(1,amount);s.setLong(2,appointmentId);if(s.executeUpdate()!=1)throw new IllegalStateException("Invoice requires one completed appointment");try(ResultSet k=s.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public void pay(long invoiceId,BigDecimal amount,String method,String reference)throws SQLException {if(amount.signum()<=0)throw new IllegalArgumentException("Payment must be positive");try(Connection c=Database.connection()){c.setAutoCommit(false);try(PreparedStatement lock=c.prepareStatement("SELECT amount,status FROM invoices WHERE id=? FOR UPDATE")){lock.setLong(1,invoiceId);try(ResultSet r=lock.executeQuery()){if(!r.next()||!"PENDING".equals(r.getString(2))||r.getBigDecimal(1).compareTo(amount)!=0)throw new IllegalStateException("Payment must exactly match a pending invoice");}try(PreparedStatement p=c.prepareStatement("INSERT INTO payments(invoice_id,amount,method,reference_no) VALUES(?,?,?,?)");PreparedStatement u=c.prepareStatement("UPDATE invoices SET status='PAID',paid_at=NOW() WHERE id=?")){p.setLong(1,invoiceId);p.setBigDecimal(2,amount);p.setString(3,method);p.setString(4,reference);p.executeUpdate();u.setLong(1,invoiceId);u.executeUpdate();c.commit();}}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
}
